/* eslint-disable max-lines-per-function, max-lines */
import { Component, State, Watch, Element, Host, Prop, Event, h, EventEmitter, VNode } from '@stencil/core';
import { Slot, Slots, Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { AdditionalTags, TagsType, AssetTileAction } from './types';
import { asObject } from '@src/shared/type-utils';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { KsDropdownMenu } from '../ks-dropdown-menu';
import { noop } from 'lodash-es';
import { RadioValue } from '@src/components/ks-radio/types';
import { Consume } from '@src/framework/runtime-context';
import { RadioGroupContext, RadioGroupContextValue } from '../ks-radio/context';
import { CheckboxGroupContext, CheckboxGroupContextValue } from '../ks-checkbox-group/context';
import { FormBaseComponent } from '../ks-form/FormBaseComponent';
import { FormContextValueReconcile } from '../ks-form/utils';
import { KsIconBlockNone, KsIconMoreVertical, KsIconSmartPlus, KsIconTiktok } from '@fe-infra/keystone-icons-stencil';

const prefix = 'asset-tile';

/**
 * @part base - The base container of the component.
 * @slot title - Slot for custom title content. Falls back to the `title` prop.
 * @slot icon - Slot for custom icon content, displayed when `src` is not set and the tile is not blocked.
 * @slot badge - Slot for custom badge content. Only shown when `mediaType` is not `'image'`.
 * @slot player - Slot for custom media player content, displayed when the tile is playing and not blocked.
 * @slot selectionControl - Slot for a custom selection control displayed in the upper-right corner. Falls back to the built-in checkbox or radio. When customized, manage and sync `checked` yourself.
 * @slot statusReason - Slot for custom content displayed inside the status tooltip when the tile has a `warning`, `error`, or `pending` status.
 */
@Component({
  tag: 'ks-asset-tile',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsAssetTile extends FormBaseComponent<boolean> {
  @Element() el!: HTMLKsAssetTileElement;

  @Consume({
    context: RadioGroupContext,
    subscribe: true,
    path: ['value', 'disabled'],
  })
  @State()
  radioGroupContext?: RadioGroupContextValue;

  @Consume({
    context: CheckboxGroupContext,
    subscribe: true,
    path: ['value', 'disabled'],
  })
  @State()
  checkboxGroupContext?: CheckboxGroupContextValue;

  get resolvedDisabled() {
    if (this.select === 'radio' && this.radioGroupContext?.disabled) return true;
    if (this.select === 'checkbox' && this.checkboxGroupContext?.disabled) return true;
    return this.disabled;
  }

  // TODO does not find a valid use case for 'carousel'
  /** The type of media, used to distinguish video and image. */
  @Prop() mediaType: 'video' | 'image' = 'image';

  /** Additional tags, used to display tags such as AI, recommendation, etc. */
  @Prop() additionalTags?: AdditionalTags;

  /** The title of the asset tile. */
  @Prop() title = '';

  /** The description or content of the asset tile. */
  @Prop() description = '';

  /** URL of the src to display in the tile. If provided and not empty, it overrides any content in the 'icon' slot. */
  @Prop() src = '';
  /** Alternative text for the image or video. */
  @Prop() alt = '';
  /** Indicates if media content is currently playing. If true, the 'player' slot content is shown. */
  @Prop() playing?: boolean;
  /** Determines when the video should start playing. 'hover' means the media starts playing when the mouse hovers over the tile. 'manual' requires a click to start playing. 'autoplay' starts playing the media automatically. */
  @Prop() playTrigger: 'hover' | 'manual' | 'autoplay' = 'hover';
  /** URL of the poster image shown before playback starts for video tiles. */
  @Prop() poster = '';
  /** Additional properties to pass to the image or video element. */
  @Prop() partProps?: {
    image?: { [key: string]: unknown; style?: Record<string, unknown> };
    video?: { [key: string]: unknown; style?: Record<string, unknown> };
  };
  /** The size of the component. Affects overall dimensions and internal element scaling. */
  @Prop() size: 'sm' | 'md' | 'lg' | 'xl' = 'sm';
  /** Determines the type of selection control displayed. 'none' means no selection control. 'radio' or 'checkbox' displays the respective control. */
  @Prop() select: 'none' | 'radio' | 'checkbox' = 'none';
  /** The aspect ratio of the component's visual area. */
  @Prop() ratio: '1:1' | '16:9' = '1:1';
  /** Loading state of the component. Set it to `false` to hide the loading overlay or provide `{ percent }` to show upload or processing progress. */
  @Prop() loading?: { percent: number } | false = false;
  /** The value associated with this asset tile, used when it's part of a selection group (radio or checkbox). */
  @Prop() @Vue2ValueFix() value?: number | string;
  /** Controls the selected state of the tile when `select` is 'radio' or 'checkbox'. Can be used for controlled component behavior. */
  @Prop() @FormContextValueReconcile({ contextKey: 'valueFromContext' }) checked?: boolean;
  /** Controls the default selected state of the tile. */
  @Prop() defaultChecked?: boolean;
  /** If true, the asset tile is non-interactive and visually styled as disabled. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** Specifies how the media from `src` should be resized to fit its container. `cover` fills the media area while preserving aspect ratio, and `contain` keeps the entire asset visible within the available space. */
  @Prop() objectFit: 'cover' | 'contain' = 'cover';
  /** Visual status indicator for the tile. `default` shows no special status. `error` displays an error indicator. `pending` shows a pending tag. `warning` displays a warning icon. */
  @Prop() @FormContextValueReconcile() status?: 'default' | 'error' | 'pending' | 'warning';
  /** If true, the tile enters a blocked state, displaying a block icon and reason (if provided), and disabling interactions. */
  @Prop() blocked: boolean | { reason: string } = false;

  /** Defines the actions shown on the tile. A single action renders as an icon button, while multiple actions are grouped into a dropdown menu. */
  @Prop() actions: AssetTileAction[] = [];

  @State() _actionSource: KsDropdownMenu['options'] = [];

  /** Text content for the badge displayed on the tile. Only shown when `mediaType` is not `'image'`. Commonly used to display video duration or carousel count. */
  @Prop() badge = '';

  /** If true, a TikTok icon badge is displayed on the tile. */
  @Prop() showTiktokBadge = false;

  /** If true, the tile stretches within the size's width range (e.g., sm: 120–159px, md: 160–199px, lg: 200–239px, xl: 240–280px) instead of using a fixed width. */
  @Prop() freeStretch = false;

  @Uncontrollable('checked', 'defaultChecked', 'ksChange') @State() _checked?: boolean;

  @State() __additionalTags: TagsType[] = [];

  @Slot({ slotname: 'title' }) private titleSlot?: Slots;
  @Slot({ slotname: 'icon' }) private iconSlot?: Slots;
  @Slot({ slotname: 'badge' }) private badgeSlot?: Slots;
  @Slot({ slotname: 'player' }) private playerSlot?: Slots;
  @Slot({ slotname: 'statusReason' }) private statusReasonSlot?: Slots;

  /** Triggered when the tile's checked state changes (either by direct click on the tile if `select` is not 'none', or by interaction with the internal checkbox/radio). Emits the new checked state (boolean). */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<boolean>; // 禁止冒泡，防止事件冒泡到radio group组件的valuechange事件
  /** Triggered when the tile's playing state changes. Emits the new playing state (boolean). */
  @Event({ bubbles: false, composed: false }) ksPlayingChange!: EventEmitter<boolean>;

  @Watch('checked')
  checkedWatcher(val?: boolean) {
    if (val !== undefined) {
      this._checked = val;
    }
  }

  @Watch('size')
  sizeWatcher() {
    this.setIconSize();
  }

  @Watch('additionalTags')
  additionalTagsWatcher() {
    const array: TagsType[] = [];
    if (this.additionalTags?.recommendation)
      array.push({
        type: 'recommend',
        content: 'Recommended',
      });
    if (this.additionalTags?.ai) array.push({ type: 'ai' });
    this.additionalTags?.others?.forEach((content) => array.push({ type: 'normal', content }));
    this.__additionalTags = array;
  }

  @State() isHovering = false;

  private get isPlaying() {
    if (this.playing !== undefined) return this.playing;

    if (this.mediaType !== 'video') return false;

    if (this.playTrigger === 'autoplay') return true;
    if (this.playTrigger === 'hover') return this.isHovering;
    return false; // manual is handled via click or external control
  }

  @Watch('playing')
  @Watch('isHovering')
  @Watch('playTrigger')
  handlePlayingChange() {
    const videoEl = this.el.shadowRoot?.querySelector('video');
    if (videoEl) {
      if (this.isPlaying) {
        videoEl.play().catch(noop);
      } else {
        videoEl.pause();
      }
    }
  }

  constructor() {
    super();
    registerPluginManager(this.el);
  }

  private get resolvedLoading() {
    const percent = asObject(this.loading)?.percent;
    return typeof percent === 'number' && percent <= 100 ? { percent } : false;
  }

  private get hasTitleSlot() {
    return Boolean(
      this.titleSlot?.length || Array.from(this.el.children).some((child) => child.getAttribute('slot') === 'title'),
    );
  }

  private observer?: MutationObserver;

  private handleMouseEnter = () => {
    if (this.resolvedDisabled || this.blocked) return;
    this.isHovering = true;
    if (this.mediaType === 'video' && this.playTrigger === 'hover' && this.playing === undefined) {
      this.ksPlayingChange.emit(true);
    }
  };

  private handleMouseLeave = () => {
    if (this.resolvedDisabled || this.blocked) return;
    this.isHovering = false;
    if (this.mediaType === 'video' && this.playTrigger === 'hover' && this.playing === undefined) {
      this.ksPlayingChange.emit(false);
    }
  };

  private handleValueChange = (event: Partial<Event> & { detail: boolean }) => {
    this.ksChange.emit(event.detail);
    const hasGroupContext =
      this.select === 'radio' ? this.radioGroupContext !== undefined : this.checkboxGroupContext !== undefined;
    if (this.checked === undefined && !hasGroupContext) {
      this._checked = event.detail;
    }
    sendActionTracking(this.el, { eventType: 'change', componentParams: { value: event.detail } });
  };

  private setIconSize() {
    let size = 48;
    switch (this.size) {
      case 'sm':
        size = 48;
        break;
      default:
        size = 64;
        break;
    }

    if (this.iconSlot) {
      const el = this.iconSlot[0];
      if (el) {
        el.setAttribute('size', `${size}px`);
        // 允许额外递归一层 childNodes
        el.childNodes.forEach((child) => {
          if (child instanceof HTMLElement) {
            child.setAttribute('size', `${size}px`);
          }
        });
      }
    }

    // Set icon-0 slot size to 14px
    const icon0Slot = Array.from(this.el.children).find((child) => child.getAttribute('slot') === 'icon-0');
    if (icon0Slot instanceof HTMLElement) {
      icon0Slot.setAttribute('size', '14px');
      icon0Slot.childNodes.forEach((child) => {
        if (child instanceof HTMLElement) {
          child.setAttribute('size', '14px');
        }
      });
    }
  }

  private renderSelectBox() {
    const select =
      this.select === 'checkbox' ? (
        <ks-checkbox
          onKsChange={this.handleValueChange}
          value={this.value}
          checked={Boolean(this._checked)}
          disabled={this.resolvedDisabled}
          data-testid="ks-asset-tile-index-9aiCBq"
        />
      ) : (
        <ks-radio
          onKsChange={this.handleValueChange}
          value={this.value}
          checked={Boolean(this._checked)}
          disabled={this.resolvedDisabled}
          data-testid="ks-asset-tile-index-szed22"
        />
      );

    return (
      <div class={`${prefix}__select-box`}>
        <slot name="selectionControl">{select}</slot>
      </div>
    );
  }

  private renderBadge() {
    if (!this.badge && !this.badgeSlot && !this.showTiktokBadge) return null;

    return (
      <div class={`${prefix}__badges`}>
        {this.mediaType !== 'image' && (
          <span class={'badge'}>
            <slot name="badge">{this.badge}</slot>
          </span>
        )}

        {this.showTiktokBadge && (
          <span
            class={{
              ['badge']: true,
              ['badge--tiktok']: true,
            }}
          >
            <KsIconTiktok class="icon-tiktok" size={14}></KsIconTiktok>
          </span>
        )}
      </div>
    );
  }

  private renderStatus() {
    const status = this.status as string | undefined;
    if (!status || status === 'default') return null;
    if (status === 'pending')
      return (
        <ks-tag size={this.size !== 'sm' ? 'md' : 'sm'} class={`${prefix}__status__pending`}>
          Pending
        </ks-tag>
      );
    return (
      <ks-status-icon
        bordered
        size={this.size !== 'sm' ? 'md' : 'sm'}
        class={`${prefix}__status__${status}`}
        variant={status as 'error' | 'warning'}
      ></ks-status-icon>
    );
  }

  private renderAction() {
    const isActionDisabled = Boolean(this.resolvedDisabled || this.blocked);

    if (this.actions.length > 1) {
      return (
        <div class={`${prefix}__action`}>
          <ks-dropdown-menu
            disabled={isActionDisabled}
            onClick={(e) => {
              e.stopPropagation();
            }}
            popoverProps={{
              trigger: 'click',
            }}
            selectable={false}
            options={this._actionSource}
            wrapWithSlot={this.wrapWithSlot}
            setDynamicRenderDeps={(children: unknown[], getPassThroughSlots?: () => VNode[]) => {
              this.setDynamicRenderDeps(children);
              this.passThroughSlots = getPassThroughSlots?.() || [];
            }}
            data-testid="ks-asset-tile-index-royWtj"
          >
            <ks-icon-button size="sm" disabled={isActionDisabled} data-testid="ks-asset-tile-index-aQsLdn">
              <KsIconMoreVertical size="14" />
            </ks-icon-button>
            {this.passThroughSlots}
          </ks-dropdown-menu>
        </div>
      );
    } else {
      return (
        <ks-icon-button
          disabled={isActionDisabled || this.actions[0]?.disabled}
          onClick={(event) => {
            event.stopPropagation();
            this.actions[0]?.onClick?.();
            sendActionTracking(this.el, { eventType: 'click', subEventType: 'action' });
          }}
          size="sm"
          class={`${prefix}__action`}
          data-testid="ks-asset-tile-index-bohWFE"
        >
          <slot name="icon-0"></slot>
        </ks-icon-button>
      );
    }
  }

  private renderAssetTileContent() {
    return (
      <div class={`${prefix}__content`}>
        <div class={`${prefix}__title__container`}>
          <div
            class={{
              [`${prefix}__title`]: true,
              [`${prefix}__title__bold`]: Boolean(this.description),
            }}
            title={this.title}
          >
            <slot name="title">{this.title}</slot>
          </div>
        </div>
        {this.description && <div class={`${prefix}__desc`}>{this.description}</div>}
      </div>
    );
  }

  private additionalTag(tag: TagsType) {
    const isAi = tag.type === 'ai';

    if (isAi)
      return (
        <ks-tooltip content="AI Generation">
          <ks-tag size="sm" variant="new">
            <KsIconSmartPlus size="14" />
          </ks-tag>
        </ks-tooltip>
      );

    return (
      <ks-tag size="sm" variant={tag.type === 'recommend' ? 'info' : 'neutral'}>
        {tag.content}
      </ks-tag>
    );
  }

  private renderAdditionalTags() {
    const showMore = this.__additionalTags.length > 2;
    const renderTags = this.__additionalTags.slice(0, 2);

    return (
      <div class={`${prefix}__additional_tags`}>
        {renderTags.map((tag) => this.additionalTag(tag))}
        {showMore && (
          <ks-tooltip>
            <div slot="content">
              {this.__additionalTags.slice(2).map((tag, index) => (
                <div>{index + 2 !== this.__additionalTags.length - 1 ? `${tag.content},` : tag.content}</div>
              ))}
            </div>
            <ks-tag size="sm">+{`${this.__additionalTags.length - renderTags.length}`}</ks-tag>
          </ks-tooltip>
        )}
      </div>
    );
  }

  private get progressSize() {
    switch (this.size) {
      case 'lg':
        return 'sm';
      case 'xl':
        return 'md';
      default:
        return 'xs';
    }
  }

  private handleClick = (event: MouseEvent) => {
    const target = event.target as HTMLElement;
    if (this.resolvedDisabled || this.resolvedLoading || target.closest('ks-checkbox, ks-radio') || this.blocked) {
      return;
    }

    if (this.mediaType === 'video' && this.playTrigger === 'manual' && this.playing === undefined) {
      this.ksPlayingChange.emit(true);
    }

    if (this.select === 'radio') {
      if (this._checked) return;
      this.radioGroupContext?.onValueChange?.(this.value as RadioValue);
    } else if (this.select === 'checkbox') {
      this.checkboxGroupContext?.onValueChange?.(this.value as string | number);
    }

    if (this.select !== 'none') {
      const detail = this.select === 'checkbox' ? !this._checked : true;
      this.handleValueChange({ detail });
    }
  };

  private reduceActions() {
    return this.actions.map((item, index) => {
      const hasIcon = typeof item.icon === 'function';
      const hasLabel = typeof item.label === 'function';
      const option: NonNullable<KsDropdownMenu['options']>[number] = {
        value: index,
        disabled: item.disabled,
        onClick: item.onClick,
      };
      if (hasIcon && !hasLabel) {
        option.label = item.icon;
      } else {
        if (hasIcon) {
          option.prefix = item.icon;
        }
        if (hasLabel) {
          option.label = item.label;
        }
      }
      return option;
    });
  }

  @Watch('actions')
  actionsWatcher() {
    this._actionSource = this.reduceActions();
  }

  componentWillLoad() {
    this.additionalTagsWatcher();
    this._actionSource = this.reduceActions();
  }

  componentDidLoad() {
    this.setIconSize();
    this.observer = new MutationObserver(() => {
      this.setIconSize();
    });
    this.observer.observe(this.el, {
      childList: true,
    });
  }

  override connectedCallback() {
    super.connectedCallback?.();

    if (this.observer) {
      this.observer.observe(this.el, {
        childList: true,
      });
    }
  }

  override disconnectedCallback() {
    this.observer?.disconnect();
    super.disconnectedCallback?.();
  }

  @State() private passThroughSlots: VNode[] = [];
  /**
   * @private
   */
  @Prop() wrapWithSlot: (slotName: string, children: unknown) => unknown = () => [];
  /**
   * @private
   */
  @Prop() setDynamicRenderDeps: (children: unknown[]) => void = noop;

  // FIXME buggy behavior in Vue
  componentWillRender() {
    if (this.actions?.length === 1) {
      const dynamicSlots: unknown[] = [];

      this.actions.forEach(({ icon }, index: number) => {
        if (typeof icon === 'function') {
          dynamicSlots.push(this.wrapWithSlot(`icon-${index}`, icon()));
        }
      });
      this.setDynamicRenderDeps(dynamicSlots);
    }
  }

  render() {
    const isVideo =
      this.mediaType === 'video' &&
      (!this.src || !/\.(jpg|jpeg|png|gif|webp|svg|bmp|image|avif|ico|tiff)([\?~#].*)?$/i.test(this.src));
    const hasSrc = Boolean(this.src);
    const hasPoster = Boolean(this.poster);

    const showVideo = isVideo && hasSrc;
    const showPoster = isVideo && hasPoster;
    const showImage = (this.mediaType === 'image' || !isVideo) && hasSrc;
    const hasAssetTileContent = Boolean(this.hasTitleSlot || this.title || this.description);

    let backgroundContent = null;
    const mediaStyle = { objectFit: this.objectFit };

    if (!this.blocked) {
      if (isVideo || this.playerSlot) {
        backgroundContent = (
          <div class={`${prefix}__background-media-container`}>
            {(showPoster || showImage) && (
              <img
                class={`${prefix}__background-media`}
                src={showPoster ? this.poster : this.src}
                alt={this.alt}
                {...this.partProps?.image}
                style={{
                  ...mediaStyle,
                  ...this.partProps?.image?.style,
                  zIndex: this.isPlaying && (showVideo || this.playerSlot) ? '1' : '2',
                }}
              />
            )}
            {this.playerSlot && this.isPlaying && (
              <div class={{ [`${prefix}__player`]: true }}>
                <slot name="player"></slot>
              </div>
            )}
            {showVideo && !this.playerSlot && (this.isPlaying || !hasPoster) && (
              <video
                class={`${prefix}__background-media`}
                src={this.src}
                poster={this.poster}
                muted
                loop
                playsInline
                ref={(el) => {
                  if (el) {
                    if (this.isPlaying) {
                      el.play().catch(noop);
                    } else {
                      el.pause();
                    }
                  }
                }}
                {...this.partProps?.video}
                style={{
                  ...mediaStyle,
                  ...this.partProps?.video?.style,
                  zIndex: this.isPlaying ? '2' : '1',
                  visibility: this.isPlaying || !hasPoster ? 'visible' : 'hidden',
                }}
              />
            )}
          </div>
        );
      } else if (showImage) {
        backgroundContent = (
          <img
            class={`${prefix}__background-media`}
            src={this.src}
            alt={this.alt}
            {...this.partProps?.image}
            style={{ ...mediaStyle, ...this.partProps?.image?.style }}
          />
        );
      }
    }

    const containerStyle = {
      background: backgroundContent
        ? 'none'
        : `var(--ks-color-neutral-surface2${this.resolvedDisabled ? 'Disabled' : ''})`,
    };

    const blockSize = this.size === 'sm' ? 42 : 56;

    return (
      <Host class={{ KsAssetTile: true, [`${prefix}--free-stretch`]: this.freeStretch }}>
        <div
          style={containerStyle}
          class={{
            [prefix]: true,
            [`${prefix}__disabled`]: Boolean(this.resolvedDisabled),
            [`${prefix}--checked`]:
              this.select !== 'none' &&
              !this.resolvedLoading &&
              Boolean(
                this._checked ||
                (this.value !== undefined &&
                  ((this.select === 'radio' && this.radioGroupContext?.value === this.value) ||
                    (this.select === 'checkbox' &&
                      this.checkboxGroupContext?.value?.includes(this.value as string | number)))),
              ),
            [`${prefix}__vertical`]: this.ratio === '16:9',
            [`${prefix}__block`]: Boolean(this.blocked),
            [`${prefix}__error`]: Boolean(this.status === 'error' && this.src),
            [`${prefix}__${this.size}__stretch`]: this.freeStretch,
            [`${prefix}__${this.size}`]: !this.freeStretch,
          }}
          onClick={this.handleClick}
          onMouseEnter={this.handleMouseEnter}
          onMouseLeave={this.handleMouseLeave}
          part="base"
          data-testid="ks-asset-tile-index-nvY97b"
        >
          {backgroundContent}
          {!this.blocked && this.select !== 'none' && !this.resolvedLoading && this.renderSelectBox()}
          {!this.blocked && this.iconSlot && !this.src && <slot name="icon"></slot>}

          {!this.blocked && this.renderBadge()}
          {!this.blocked && this.status !== 'default' && (
            <span class={`${prefix}__status`}>
              <ks-tooltip>
                {this.statusReasonSlot && <slot name="statusReason" slot="content"></slot>}
                {this.renderStatus()}
              </ks-tooltip>
            </span>
          )}

          {!this.blocked && this.actions.length > 0 && this.renderAction()}

          {!this.blocked && this.resolvedLoading && (
            <div class={`${prefix}__loading`}>
              <div class={`${prefix}__loading-ring`}>
                <ks-progress
                  variant={'ring'}
                  percent={this.resolvedLoading.percent}
                  size={this.progressSize}
                ></ks-progress>
                {/* TODO I18n */}
                <span>Loading.....</span>
              </div>
            </div>
          )}

          {this.blocked && (
            <ks-tooltip
              popupWidth={{ max: '240px' }}
              disabled={!asObject(this.blocked)?.reason}
              content={asObject(this.blocked)?.reason}
            >
              <div class={`${prefix}__block-container`}>
                <KsIconBlockNone size={blockSize}></KsIconBlockNone>
              </div>
            </ks-tooltip>
          )}
        </div>
        {(hasAssetTileContent || this.additionalTags) && (
          <div class={`${prefix}__extra ${prefix}__${this.size}`}>
            {hasAssetTileContent && this.renderAssetTileContent()}
            {this.additionalTags && this.renderAdditionalTags()}
          </div>
        )}
      </Host>
    );
  }
}
